import Foundation

/// Public-domain showcase ROMs bundled with the app (generated by tools/showcase), so a fresh
/// install has something to play: added once on first launch when the ROMs folder is empty,
/// and again on request from Settings.
enum DemoGames {
    /// Bundled file → name in the library.
    static let files = [
        ("snes-showcase.sfc", "Rolling Hills (Demo).sfc"),
        ("genesis-showcase.md", "Neon Horizon (Demo).md"),
        ("ds-showcase.nds", "Sunset Lake (Demo).nds"),
    ]
    private static let offeredKey = "demoGamesOffered"

    static func installOnFirstLaunch() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: offeredKey) else { return }
        defaults.set(true, forKey: offeredKey)
        let existing = (try? FileManager.default.contentsOfDirectory(
            at: GamePaths.roms, includingPropertiesForKeys: nil, options: [.skipsHiddenFiles])) ?? []
        guard existing.isEmpty else { return }
        install()
    }

    /// Copies any demo game that's missing; returns how many were added.
    @discardableResult
    static func install() -> Int {
        GamePaths.ensureDirectories()
        var added = 0
        for (resource, name) in files {
            let target = GamePaths.roms.appending(path: name)
            let parts = resource.split(separator: ".", maxSplits: 1).map(String.init)
            guard !FileManager.default.fileExists(atPath: target.path),
                  let source = Bundle.main.url(forResource: parts[0], withExtension: parts[1]),
                  (try? FileManager.default.copyItem(at: source, to: target)) != nil else { continue }
            added += 1
        }
        return added
    }
}
